		JdbcTemplate jdbc = new JdbcTemplate(this.dataSource);
		jdbc.update("DELETE FROM t_user");

		User u = new User();
		u.setId(1L);
		u.setName("U1");
		u.setMobile("18800000000");
		u.setEmail("u1@example.com");
