		Assertions.assertNotNull(raw.getMobile());
		Assertions.assertNotEquals("18800000000", raw.getMobile());
		Assertions.assertNotNull(raw.getEmail());
		Assertions.assertNotEquals("u1@example.com", raw.getEmail());

