		LambdaQueryWrapper<User> w = Wrappers.lambdaQuery(User.class).eq(User::getMobile, "18800000000");
		User got = this.userMapper.selectOne(w);
		Assertions.assertNotNull(got);
		Assertions.assertEquals(1, got.getId());
	}
